<script setup>
import IeltsNavigation from '../components/IeltsNavigation.vue'
import {ref,onMounted} from 'vue'
import ielts from '../api/ielts.js'
const data=ref(null),error=ref(''),busy=ref(null)
function sourceLink(value){const match=/^attempt:(\d+):/.exec(value);return match?`/ielts/attempt/${match[1]}`:'/ielts/vocabulary'}
const names={recognition:'识义',listening:'听辨',spelling:'拼写',collocation:'搭配',paraphrase:'同义替换',single:'单选',multiple:'多选',completion:'填空',headings:'标题匹配',true_false:'事实判断',yes_no:'观点判断',matching:'匹配',map:'地图标注',diagram:'图示标注',short_answer:'简答',expression:'表达'}
async function load(){try{data.value=await ielts.overview()}catch(e){error.value=e.message}}
async function decide(s,state){busy.value=s.id;error.value='';try{await ielts.suggestion(s.id,state);await load()}catch(e){error.value=e.message}finally{busy.value=null}}
onMounted(load)
</script>
<template><div class="ielts-page"><IeltsNavigation/><header class="ielts-heading"><div><h1>学习档案</h1><p>保留作答、证据和变化，让下一步训练更有方向。</p></div><router-link class="btn btn-ghost" to="/dashboard">词汇学习看板</router-link></header><p v-if="error" class="ielts-error" role="alert">{{error}}</p><template v-if="data"><section class="ielts-section"><h2>分能力表现</h2><p v-if="!data.evidence.length" class="muted">完成一组训练后，这里会开始积累真实表现。</p><div v-for="e in data.evidence" :key="e.skill+e.ability" class="ielts-list-row"><span>{{({vocabulary:'词汇',listening:'听力',reading:'阅读',writing:'写作',speaking:'口语'})[e.skill]}} · {{names[e.ability]||e.ability}}</span><span>{{e.correct||0}} / {{e.total}} 条正确证据</span></div></section><section class="ielts-section"><h2>待确认的复习建议</h2><p v-if="!data.suggestions.length" class="muted">暂时没有待确认建议，错题中的薄弱词会在这里出现。</p><article v-for="s in data.suggestions" :key="s.id" class="ielts-list-row"><span><strong>{{s.spelling}}</strong><small>{{s.note}}</small><small><router-link :to="sourceLink(s.source_key)">回看练习来源</router-link></small></span><span class="ielts-inline-actions"><button class="btn btn-ghost" :disabled="busy!==null" @click="decide(s,'accepted')">加入复习</button><button class="btn btn-ghost" :disabled="busy!==null" @click="decide(s,'dismissed')">暂不加入</button></span></article></section><section class="ielts-section"><h2>训练与模考记录</h2><p v-if="!data.attempts.length" class="muted">还没有训练记录。</p><router-link v-for="a in data.attempts" :key="a.id" :to="`/ielts/attempt/${a.id}`" class="ielts-list-row"><span><strong>{{a.title}}</strong><small>{{new Date(a.updated_at).toLocaleString('zh-CN')}} · 第 {{a.version}} 版</small></span><span>{{a.state==='submitted'?'查看复盘':a.state==='paused'?'继续训练':'恢复进度'}}</span></router-link></section></template></div></template>
